@dataclass
class RootIsolationStats:
    calls: int = 0
    cache_hits: int = 0
    cache_misses: int = 0
    refinements: int = 0
    comparison_refinements: int = 0
    sign_hits: int = 0
    sign_misses: int = 0
    comparison_hits: int = 0
    comparison_misses: int = 0
    specialization_hits: int = 0
    specialization_misses: int = 0
    rur_hits: int = 0
    rur_misses: int = 0
    tower_escapes: int = 0
    family_relationship_hits: int = 0
    family_relationship_misses: int = 0
    number_field_fallbacks: int = 0
    number_field_refinement_fallbacks: int = 0
    refinement_requests: dict[str, int] = field(default_factory=dict)
    refinement_advances: dict[str, int] = field(default_factory=dict)
    refinement_decisive_advances: dict[str, int] = field(default_factory=dict)
    sign_refinement_advances: dict[str, int] = field(default_factory=dict)
    sign_refinement_chain_lengths: dict[str, dict[int, int]] = field(default_factory=dict)
    sign_refinement_coordinates: dict[str, dict[str, int]] = field(default_factory=dict)


